-- Document Loaders Category
INSERT INTO workflow_node_types (category_id, type_key, display_name, description, detailed_explanation, icon, capabilities, requirements, order_index)
SELECT 
  c.id,
  doc_data.type_key,
  doc_data.display_name,
  doc_data.description,
  doc_data.detailed_explanation,
  doc_data.icon,
  doc_data.capabilities,
  doc_data.requirements,
  doc_data.order_index
FROM workflow_node_categories c,
(VALUES
  ('api_loader', 'API Loader', 'Load data from REST APIs', 'API Loader fetches data from RESTful web services and APIs. It handles authentication, rate limiting, pagination, and data transformation. Perfect for integrating with external services, fetching real-time data, and building data pipelines from web APIs.', 'globe', '["api_integration", "authentication", "rate_limiting", "pagination"]', '{"api_endpoint": true, "auth_method": "optional"}', 1),
  ('airtable_loader', 'Airtable Loader', 'Load data from Airtable databases', 'Airtable Loader integrates with Airtable databases to fetch records, tables, and workspace data. It understands Airtable''s data types, relationships, and provides efficient bulk data loading with field mapping capabilities.', 'database', '["airtable_integration", "bulk_loading", "field_mapping", "relationship_handling"]', '{"airtable_api_key": true, "base_id": true}', 2),
  ('brave_search_loader', 'BraveSearch API Document Loader', 'Web search integration via Brave Search', 'BraveSearch Document Loader uses Brave Search API to find and retrieve web documents based on search queries. It provides privacy-focused web search with document extraction capabilities, perfect for research and content aggregation workflows.', 'search', '["web_search", "privacy_focused", "document_extraction", "content_aggregation"]', '{"brave_api_key": true, "search_queries": true}', 3),
  ('cheerio_scraper', 'Cheerio Web Scraper', 'HTML parsing and web scraping', 'Cheerio Web Scraper uses jQuery-like server-side HTML parsing to extract structured data from web pages. It''s perfect for scraping websites, extracting specific elements, and transforming HTML content into structured data.', 'code', '["html_parsing", "css_selectors", "data_extraction", "content_transformation"]', '{"target_urls": true, "css_selectors": true}', 4),
  ('confluence_loader', 'Confluence Loader', 'Load content from Atlassian Confluence', 'Confluence Loader integrates with Atlassian Confluence to fetch pages, spaces, and documentation. It handles authentication, hierarchy navigation, and content formatting, making it ideal for knowledge base integration and documentation workflows.', 'book', '["confluence_api", "content_extraction", "hierarchy_navigation", "authentication"]', '{"confluence_url": true, "auth_credentials": true}', 5),
  ('csv_loader', 'CSV File Loader', 'Load and parse CSV files', 'CSV File Loader reads and parses comma-separated value files with support for various delimiters, encoding types, and data validation. It provides schema inference, data type conversion, and error handling for robust data ingestion.', 'table', '["csv_parsing", "schema_inference", "data_validation", "encoding_support"]', '{"file_path": true, "delimiter": "optional"}', 6),
  ('custom_document_loader', 'Custom Document Loader', 'Custom document processing logic', 'Custom Document Loader allows you to implement specialized document processing logic for unique formats or sources. It provides a flexible framework for handling custom file types, proprietary formats, and specialized data extraction requirements.', 'file', '["custom_processing", "flexible_formats", "specialized_extraction", "framework_support"]', '{"custom_logic": true, "processing_function": true}', 7),
  ('document_store_loader', 'Document Store Loader', 'Load from document databases', 'Document Store Loader integrates with NoSQL document databases like MongoDB, CouchDB, and others. It handles complex queries, document retrieval, and data transformation from document-oriented storage systems.', 'database', '["nosql_integration", "document_queries", "data_transformation", "bulk_retrieval"]', '{"database_connection": true, "query_language": true}', 8),
  ('docx_loader', 'DocX File Loader', 'Microsoft Word document processing', 'DocX File Loader extracts text, metadata, and formatting from Microsoft Word documents. It handles complex document structures, embedded objects, and preserves formatting information for comprehensive document analysis.', 'file-text', '["docx_parsing", "metadata_extraction", "formatting_preservation", "structure_analysis"]', '{"file_path": true, "extraction_options": "optional"}', 9),
  ('epub_loader', 'EPUB File Loader', 'Electronic publication format support', 'EPUB File Loader processes electronic publication files, extracting chapters, metadata, and content structure. Perfect for digital library integration, e-book analysis, and publishing workflow automation.', 'book-open', '["epub_parsing", "chapter_extraction", "metadata_processing", "content_structure"]', '{"file_path": true, "chapter_selection": "optional"}', 10),
  ('figma_loader', 'Figma Loader', 'Design file integration from Figma', 'Figma Loader integrates with Figma''s API to extract design files, components, and project data. It''s perfect for design system automation, asset extraction, and design-to-development workflows.', 'figma', '["figma_api", "design_extraction", "component_analysis", "asset_management"]', '{"figma_token": true, "file_id": true}', 11),
  ('file_loader', 'File Loader', 'Generic file loading and processing', 'File Loader provides generic file handling capabilities with support for multiple formats, encoding detection, and content extraction. It serves as a universal file processor with pluggable format handlers.', 'file', '["multi_format_support", "encoding_detection", "content_extraction", "universal_processing"]', '{"file_path": true, "format_detection": true}', 12),
  ('firecrawl_loader', 'FireCrawl Loader', 'Advanced web crawling and scraping', 'FireCrawl Loader provides advanced web crawling capabilities with JavaScript rendering, intelligent content extraction, and scalable crawling infrastructure. Perfect for large-scale web data collection and content analysis.', 'spider', '["web_crawling", "javascript_rendering", "content_intelligence", "scalable_infrastructure"]', '{"firecrawl_api_key": true, "crawl_config": true}', 13),
  ('github_loader', 'GitHub Loader', 'Repository and issue data extraction', 'GitHub Loader integrates with GitHub''s API to fetch repositories, issues, pull requests, and code content. It''s ideal for software development analytics, code analysis, and project management integration.', 'github', '["github_api", "repository_analysis", "issue_tracking", "code_extraction"]', '{"github_token": true, "repository_access": true}', 14),
  ('google_drive_loader', 'Google Drive Loader', 'Google Drive file integration', 'Google Drive Loader accesses files and folders from Google Drive with support for various file types, sharing permissions, and collaborative features. Perfect for document management and team collaboration workflows.', 'drive', '["google_drive_api", "file_management", "permission_handling", "collaborative_features"]', '{"google_credentials": true, "drive_access": true}', 15),
  ('google_sheets_loader', 'Google Sheets Loader', 'Spreadsheet data integration', 'Google Sheets Loader reads and processes data from Google Sheets with support for multiple sheets, formulas, and real-time updates. Ideal for data analysis, reporting, and collaborative data management.', 'sheet', '["sheets_api", "formula_support", "real_time_updates", "multi_sheet_processing"]', '{"google_credentials": true, "sheet_id": true}', 16),
  ('jira_loader', 'JIRA Loader', 'Atlassian JIRA integration', 'JIRA Loader integrates with Atlassian JIRA to fetch issues, projects, and workflow data. It supports custom fields, advanced queries, and provides comprehensive project management data integration.', 'ticket', '["jira_api", "issue_management", "custom_fields", "advanced_queries"]', '{"jira_credentials": true, "project_access": true}', 17),
  ('json_loader', 'JSON File Loader', 'JSON data processing and validation', 'JSON File Loader parses and validates JSON files with schema validation, nested object handling, and data transformation capabilities. Perfect for configuration files, API responses, and structured data processing.', 'braces', '["json_parsing", "schema_validation", "nested_objects", "data_transformation"]', '{"file_path": true, "schema": "optional"}', 18),
  ('jsonlines_loader', 'JSON Lines File Loader', 'Streaming JSON data processing', 'JSON Lines File Loader processes JSONL files with streaming support for large datasets. It handles line-by-line JSON parsing, memory-efficient processing, and real-time data ingestion.', 'list', '["streaming_processing", "memory_efficient", "line_by_line", "real_time_ingestion"]', '{"file_path": true, "streaming_config": "optional"}', 19),
  ('excel_loader', 'Microsoft Excel Loader', 'Excel file processing and analysis', 'Microsoft Excel Loader reads and processes Excel files with support for multiple worksheets, formulas, charts, and complex formatting. It provides comprehensive spreadsheet analysis and data extraction capabilities.', 'file-spreadsheet', '["excel_processing", "multi_worksheet", "formula_support", "chart_analysis"]', '{"file_path": true, "worksheet_selection": "optional"}', 20),
  ('powerpoint_loader', 'Microsoft PowerPoint Loader', 'Presentation file processing', 'Microsoft PowerPoint Loader extracts content, images, and metadata from PowerPoint presentations. It handles slide content, speaker notes, and embedded objects for comprehensive presentation analysis.', 'presentation', '["pptx_processing", "slide_extraction", "image_handling", "metadata_analysis"]', '{"file_path": true, "slide_selection": "optional"}', 21),
  ('notion_database_loader', 'Notion Database Loader', 'Notion database integration', 'Notion Database Loader integrates with Notion databases to fetch pages, properties, and relational data. It handles Notion''s block structure and provides efficient data synchronization for knowledge management workflows.', 'database', '["notion_api", "database_queries", "block_processing", "relation_handling"]', '{"notion_token": true, "database_id": true}', 22),
  ('notion_page_loader', 'Notion Page Loader', 'Notion page content extraction', 'Notion Page Loader extracts content from Notion pages including text, images, and embedded blocks. It preserves page structure and formatting for comprehensive content analysis and migration workflows.', 'file-text', '["page_extraction", "block_processing", "content_preservation", "structure_analysis"]', '{"notion_token": true, "page_id": true}', 23),
  ('pdf_loader', 'PDF Files Loader', 'PDF document processing and extraction', 'PDF Files Loader extracts text, images, and metadata from PDF documents with support for OCR, table extraction, and form processing. It handles complex PDF structures and provides accurate content extraction.', 'file-type', '["pdf_extraction", "ocr_support", "table_processing", "form_handling"]', '{"file_path": true, "extraction_mode": "optional"}', 24),
  ('playwright_scraper', 'Playwright Web Scraper', 'Modern web scraping with browser automation', 'Playwright Web Scraper provides modern web scraping with full browser automation, JavaScript execution, and dynamic content handling. Perfect for scraping modern web applications and SPA content.', 'browser', '["browser_automation", "javascript_execution", "dynamic_content", "modern_web_support"]', '{"target_urls": true, "browser_config": "optional"}', 25),
  ('puppeteer_scraper', 'Puppeteer Web Scraper', 'Headless Chrome automation for scraping', 'Puppeteer Web Scraper uses headless Chrome for web scraping with JavaScript execution, screenshot capture, and dynamic content handling. Ideal for modern web applications and complex scraping scenarios.', 'chrome', '["headless_chrome", "javascript_execution", "screenshot_capture", "dynamic_scraping"]', '{"target_urls": true, "chrome_config": "optional"}', 26),
  ('s3_directory_loader', 'S3 Directory Loader', 'AWS S3 directory content processing', 'S3 Directory Loader processes entire directories from AWS S3 buckets with support for filtering, recursive processing, and metadata extraction. Perfect for bulk data processing and cloud storage integration.', 'folder', '["s3_integration", "directory_processing", "filtering_support", "metadata_extraction"]', '{"aws_credentials": true, "bucket_name": true}', 27),
  ('s3_loader', 'S3 Loader', 'AWS S3 object storage integration', 'S3 Loader integrates with AWS S3 for object storage operations including file upload, download, and metadata management. It provides efficient cloud storage integration with advanced features.', 'cloud', '["s3_operations", "object_management", "metadata_handling", "cloud_integration"]', '{"aws_credentials": true, "bucket_access": true}', 28),
  ('searchapi_loader', 'SearchAPI for Web Search', 'Web search API integration', 'SearchAPI Loader integrates with web search APIs to perform search queries and retrieve results. It supports multiple search engines and provides structured search result processing for research workflows.', 'search', '["web_search_api", "multi_engine_support", "result_processing", "structured_output"]', '{"search_api_key": true, "search_engines": true}', 29),
  ('serpapi_loader', 'SerpAPI for Web Search', 'Google Search API integration', 'SerpAPI Loader integrates with SerpAPI for Google Search results extraction. It provides structured access to search results, images, news, and other Google search features with API-based access.', 'google', '["google_search_api", "structured_results", "multi_format_support", "api_integration"]', '{"serpapi_key": true, "search_parameters": true}', 30),
  ('spider_loader', 'Spider Document Loader', 'Distributed web crawling system', 'Spider Document Loader provides distributed web crawling capabilities with intelligent link discovery, content extraction, and scalable processing. Perfect for large-scale web data collection and site analysis.', 'spider', '["distributed_crawling", "link_discovery", "intelligent_extraction", "scalable_processing"]', '{"spider_config": true, "crawl_rules": true}', 31),
  ('text_loader', 'Text File Loader', 'Plain text file processing', 'Text File Loader processes plain text files with encoding detection, line processing, and content analysis. It provides efficient text data ingestion with support for various text formats and encodings.', 'file-text', '["text_processing", "encoding_detection", "line_analysis", "content_extraction"]', '{"file_path": true, "encoding": "optional"}', 32),
  ('unstructured_loader', 'Unstructured File Loader', 'Multi-format unstructured data processing', 'Unstructured File Loader handles various unstructured file formats with intelligent content extraction, layout analysis, and structure detection. Perfect for processing diverse document types and legacy formats.', 'file-question', '["multi_format_support", "intelligent_extraction", "layout_analysis", "structure_detection"]', '{"file_path": true, "processing_mode": "optional"}', 33),
  ('vectorstore_to_document', 'Vectorstore to Document', 'Convert vector data to documents', 'Vectorstore to Document converts stored vector embeddings back into readable document format. It''s useful for data export, analysis, and converting between vector and text representations.', 'arrow-right', '["vector_conversion", "document_generation", "data_export", "format_transformation"]', '{"vectorstore_connection": true, "conversion_rules": true}', 34)
) AS doc_data(type_key, display_name, description, detailed_explanation, icon, capabilities, requirements, order_index)
WHERE c.name = 'document_loaders';

-- Tools Category  
INSERT INTO workflow_node_types (category_id, type_key, display_name, description, detailed_explanation, icon, capabilities, requirements, order_index)
SELECT 
  c.id,
  tool_data.type_key,
  tool_data.display_name,
  tool_data.description,
  tool_data.detailed_explanation,
  tool_data.icon,
  tool_data.capabilities,
  tool_data.requirements,
  tool_data.order_index
FROM workflow_node_categories c,
(VALUES
  ('calculator_tool', 'Calculator', 'Mathematical calculations and computations', 'Calculator Tool provides comprehensive mathematical computation capabilities including basic arithmetic, advanced functions, statistical calculations, and formula evaluation. Perfect for data analysis, financial calculations, and mathematical workflows.', 'calculator', '["arithmetic_operations", "advanced_functions", "statistical_calculations", "formula_evaluation"]', '{"expression_input": true}', 1),
  ('brave_search_tool', 'BraveSearch API', 'Privacy-focused web search integration', 'BraveSearch API Tool integrates with Brave Search for privacy-focused web searches. It provides search results without tracking, making it ideal for research workflows that prioritize user privacy and data protection.', 'search', '["privacy_focused_search", "web_results", "no_tracking", "research_support"]', '{"brave_api_key": true}', 2),
  ('chain_tool', 'Chain Tool', 'Tool chaining and workflow composition', 'Chain Tool enables the composition and chaining of multiple tools in sequence or parallel. It manages data flow between tools, handles dependencies, and creates complex workflows from simple tool combinations.', 'link', '["tool_chaining", "workflow_composition", "dependency_management", "data_flow"]', '{"tool_definitions": true, "chain_config": true}', 3),
  ('chatflow_tool', 'Chatflow Tool', 'Conversational workflow integration', 'Chatflow Tool integrates conversational AI capabilities into workflows. It manages chat contexts, handles multi-turn conversations, and provides natural language interfaces for complex workflow interactions.', 'message-circle', '["conversational_ai", "context_management", "multi_turn_dialog", "natural_language_interface"]', '{"chat_model": true, "conversation_config": true}', 4),
  ('code_interpreter_e2b', 'Code Interpreter by E2B', 'Secure code execution environment', 'Code Interpreter by E2B provides secure, sandboxed code execution for multiple programming languages. It offers isolated environments, dependency management, and safe code execution for data analysis and automation workflows.', 'code', '["secure_execution", "multi_language_support", "sandboxed_environment", "dependency_management"]', '{"e2b_api_key": true, "execution_environment": true}', 5),
  ('composio_tool', 'Composio', 'Multi-platform integration tool', 'Composio Tool provides unified integration with multiple platforms and services through a single interface. It simplifies complex integrations and provides consistent APIs across different service providers.', 'plug', '["multi_platform_integration", "unified_api", "service_abstraction", "consistent_interface"]', '{"composio_api_key": true, "platform_configs": true}', 6),
  ('current_datetime_tool', 'Current DateTime', 'Date and time utilities', 'Current DateTime Tool provides current date, time, and timezone information with formatting options. It supports various date formats, timezone conversions, and date arithmetic for time-based workflows.', 'clock', '["datetime_operations", "timezone_support", "format_conversion", "date_arithmetic"]', '{}', 7),
  ('custom_tool', 'Custom Tool', 'User-defined custom functionality', 'Custom Tool allows users to define and implement custom functionality for specialized use cases. It provides a framework for creating reusable tools with custom logic, parameters, and integrations.', 'wrench', '["custom_logic", "user_defined", "reusable_components", "specialized_functionality"]', '{"custom_implementation": true, "parameter_schema": true}', 8),
  ('exa_search_tool', 'Exa Search', 'AI-powered search and discovery', 'Exa Search Tool provides AI-powered search capabilities with semantic understanding and intelligent result ranking. It excels at finding relevant information using natural language queries and contextual understanding.', 'brain', '["ai_powered_search", "semantic_understanding", "intelligent_ranking", "contextual_queries"]', '{"exa_api_key": true, "search_parameters": true}', 9),
  ('gmail_tool', 'Gmail', 'Gmail integration and email automation', 'Gmail Tool integrates with Gmail for email automation, including sending, reading, and managing emails. It supports filters, labels, attachments, and provides comprehensive email workflow capabilities.', 'mail', '["email_automation", "message_management", "filter_support", "attachment_handling"]', '{"gmail_credentials": true, "oauth_setup": true}', 10),
  ('google_calendar_tool', 'Google Calendar', 'Calendar management and scheduling', 'Google Calendar Tool integrates with Google Calendar for event management, scheduling, and calendar automation. It supports event creation, updates, invitations, and calendar synchronization.', 'calendar', '["event_management", "scheduling_automation", "calendar_sync", "invitation_handling"]', '{"google_credentials": true, "calendar_access": true}', 11),
  ('google_docs_tool', 'Google Docs', 'Document creation and collaboration', 'Google Docs Tool integrates with Google Docs for document creation, editing, and collaboration. It supports content management, formatting, sharing, and collaborative document workflows.', 'file-text', '["document_automation", "content_management", "collaboration_features", "formatting_support"]', '{"google_credentials": true, "docs_access": true}', 12),
  ('google_drive_tool', 'Google Drive', 'File storage and management', 'Google Drive Tool provides file storage, sharing, and management capabilities. It supports file operations, folder management, permissions, and collaborative file workflows with Google Drive integration.', 'drive', '["file_management", "storage_operations", "permission_handling", "collaborative_workflows"]', '{"google_credentials": true, "drive_access": true}', 13),
  ('google_custom_search_tool', 'Google Custom Search', 'Custom search engine integration', 'Google Custom Search Tool integrates with Google Custom Search Engine for domain-specific search capabilities. It provides targeted search results with custom ranking and filtering options.', 'search', '["custom_search_engine", "domain_specific_search", "targeted_results", "custom_ranking"]', '{"google_api_key": true, "search_engine_id": true}', 14),
  ('google_sheets_tool', 'Google Sheets', 'Spreadsheet automation and data management', 'Google Sheets Tool automates spreadsheet operations including data entry, formula calculations, chart creation, and sheet management. Perfect for data analysis and reporting workflows.', 'sheet', '["spreadsheet_automation", "data_manipulation", "formula_calculations", "chart_creation"]', '{"google_credentials": true, "sheets_access": true}', 15),
  ('jira_tool', 'JIRA', 'Project management and issue tracking', 'JIRA Tool integrates with Atlassian JIRA for project management, issue tracking, and workflow automation. It supports ticket creation, updates, transitions, and comprehensive project management features.', 'ticket', '["project_management", "issue_tracking", "workflow_automation", "ticket_management"]', '{"jira_credentials": true, "project_access": true}', 16),
  ('outlook_tool', 'Microsoft Outlook', 'Email and calendar integration', 'Microsoft Outlook Tool integrates with Outlook for email management, calendar scheduling, and contact management. It provides comprehensive Office 365 integration for business workflows.', 'mail', '["email_management", "calendar_integration", "contact_management", "office365_integration"]', '{"outlook_credentials": true, "office365_access": true}', 17),
  ('teams_tool', 'Microsoft Teams', 'Team collaboration and communication', 'Microsoft Teams Tool integrates with Microsoft Teams for messaging, file sharing, and team collaboration. It supports channel management, notifications, and collaborative workspace features.', 'users', '["team_collaboration", "messaging_automation", "file_sharing", "workspace_management"]', '{"teams_credentials": true, "team_access": true}', 18),
  ('openapi_toolkit', 'Open API Toolkit', 'OpenAPI specification integration', 'Open API Toolkit provides automatic integration with any OpenAPI-compliant service. It generates tool interfaces from OpenAPI specifications, enabling seamless API integration and testing.', 'code', '["openapi_integration", "automatic_generation", "api_testing", "specification_parsing"]', '{"openapi_spec": true, "authentication": "optional"}', 19),
  ('requests_delete_tool', 'Requests Delete', 'HTTP DELETE request automation', 'Requests Delete Tool performs HTTP DELETE operations with authentication, headers, and error handling. Perfect for REST API integrations requiring resource deletion capabilities.', 'trash', '["http_delete", "authentication_support", "header_management", "error_handling"]', '{"target_url": true, "auth_config": "optional"}', 20),
  ('requests_get_tool', 'Requests Get', 'HTTP GET request automation', 'Requests Get Tool performs HTTP GET operations with support for query parameters, authentication, and response processing. Ideal for data fetching and API integration workflows.', 'download', '["http_get", "query_parameters", "authentication_support", "response_processing"]', '{"target_url": true, "parameters": "optional"}', 21),
  ('requests_post_tool', 'Requests Post', 'HTTP POST request automation', 'Requests Post Tool performs HTTP POST operations with payload support, file uploads, and authentication. Perfect for data submission and API integration requiring content creation.', 'upload', '["http_post", "payload_support", "file_uploads", "authentication_support"]', '{"target_url": true, "payload": true}', 22),
  ('requests_put_tool', 'Requests Put', 'HTTP PUT request automation', 'Requests Put Tool performs HTTP PUT operations for resource updates and replacements. It supports full payload replacement, authentication, and comprehensive HTTP header management.', 'edit', '["http_put", "resource_updates", "payload_replacement", "header_management"]', '{"target_url": true, "payload": true}', 23),
  ('retriever_tool', 'Retriever Tool', 'Vector database search and retrieval', 'Retriever Tool performs semantic search and retrieval from vector databases. It supports similarity search, metadata filtering, and provides relevant document retrieval for RAG workflows.', 'search', '["semantic_search", "vector_retrieval", "metadata_filtering", "rag_support"]', '{"vector_database": true, "search_config": true}', 24),
  ('searchapi_tool', 'SearchAPI', 'Multi-engine web search integration', 'SearchAPI Tool provides access to multiple search engines through a unified interface. It supports various search types, result formatting, and search engine optimization for research workflows.', 'search', '["multi_engine_search", "unified_interface", "result_formatting", "search_optimization"]', '{"searchapi_key": true, "search_config": true}', 25),
  ('searxng_tool', 'SearXNG', 'Privacy-focused metasearch engine', 'SearXNG Tool integrates with the privacy-focused SearXNG metasearch engine. It provides anonymous search capabilities across multiple search engines without tracking or data collection.', 'shield', '["privacy_focused", "metasearch_engine", "anonymous_search", "no_tracking"]', '{"searxng_instance": true, "search_config": "optional"}', 26),
  ('serpapi_tool', 'SerpAPI', 'Google Search API integration', 'SerpAPI Tool integrates with SerpAPI for structured Google Search results. It provides access to search results, images, news, shopping, and other Google search features through API.', 'google', '["google_search_api", "structured_results", "multi_format_search", "feature_access"]', '{"serpapi_key": true, "search_parameters": true}', 27),
  ('stripe_agent_tool', 'Stripe Agent Tool', 'Payment processing automation', 'Stripe Agent Tool integrates with Stripe for payment processing, subscription management, and financial transaction automation. Perfect for e-commerce and subscription-based workflows.', 'credit-card', '["payment_processing", "subscription_management", "transaction_automation", "financial_integration"]', '{"stripe_api_key": true, "webhook_config": "optional"}', 28),
  ('web_browser_tool', 'Web Browser', 'Browser automation and web interaction', 'Web Browser Tool provides browser automation capabilities including page navigation, form filling, clicking, and content extraction. Perfect for web testing and automated web interactions.', 'globe', '["browser_automation", "web_interaction", "form_automation", "content_extraction"]', '{"browser_config": true, "target_urls": true}', 29),
  ('tavily_api_tool', 'Tavily API', 'AI-powered search and research', 'Tavily API Tool provides AI-powered search capabilities optimized for research and factual information retrieval. It offers high-quality, curated search results with source verification.', 'brain', '["ai_powered_search", "research_optimization", "fact_verification", "curated_results"]', '{"tavily_api_key": true, "search_parameters": true}', 30),
  ('web_scraper_tool', 'Web Scraper Tool', 'Advanced web scraping capabilities', 'Web Scraper Tool provides advanced web scraping with JavaScript execution, dynamic content handling, and intelligent data extraction. Perfect for modern web applications and complex scraping scenarios.', 'spider', '["advanced_scraping", "javascript_execution", "dynamic_content", "intelligent_extraction"]', '{"target_urls": true, "scraping_config": true}', 31)
) AS tool_data(type_key, display_name, description, detailed_explanation, icon, capabilities, requirements, order_index)
WHERE c.name = 'tools';